#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum RemainsSupersededRevocationJoin {
    RemainsSupersededRevocationsJoined,
    RemainsSupersededRevocationOnUnretiredNode {
        node: RoadmapNodeId,
    },
    RemainsSupersededRevocationOnUndeclaredNode {
        node: RoadmapNodeId,
    },
    RemainsSupersededRevocationOnAmbiguousDeclaredNode {
        node: RoadmapNodeId,
    },
}
impl RemainsSupersededRevocationJoin {
    pub fn node(&self) -> RoadmapNodeId {
        match self {
            RemainsSupersededRevocationJoin::RemainsSupersededRevocationsJoined => panic!("no node on unit variant"),
            RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnUnretiredNode { node: __val, .. } => __val.clone(),
            RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnUndeclaredNode { node: __val, .. } => __val.clone(),
            RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnAmbiguousDeclaredNode { node: __val, .. } => __val.clone(),
        }
    }
}

pub fn join_remains_superseded_to_declared_node(node: NonEmptyStr, nodes: Rc<Vec<Rc<RoadmapNode>>>, retired: Rc<Vec<NonEmptyStr>>) -> Rc<RemainsSupersededRevocationJoin> {
    {
        let found = Rc::new({ let mut __result = Vec::new(); for n in nodes.iter().cloned() { if (n.node.clone() == node.clone()) { __result.push(n); } } __result });
if ((found.clone().len() as i64) == 0) {
            Rc::new(RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnUndeclaredNode {
    node: node.clone(),
})
        } else {
            if ((found.clone().len() as i64) > 1) {
                Rc::new(RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnAmbiguousDeclaredNode {
    node: node.clone(),
})
            } else {
                match found.clone().first().cloned() {
    std::option::Option::None => Rc::new(RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnUndeclaredNode {
    node: node.clone(),
}),
    Some(rn) => if roadmap_node_ids_contain(retired, node.clone()) {
                    Rc::new(RemainsSupersededRevocationJoin::RemainsSupersededRevocationsJoined)
                } else {
                    Rc::new(RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnUnretiredNode {
    node: node.clone(),
})
                },
}
            }
        }
}
}

pub fn remains_superseded_revocation_event_join(event: Rc<RoadmapAcceptanceEvent>, nodes: Rc<Vec<Rc<RoadmapNode>>>, retired: Rc<Vec<NonEmptyStr>>) -> Rc<RemainsSupersededRevocationJoin> {
    match (*event.clone()).clone() {
    RoadmapAcceptanceEvent::AcceptanceRecorded { receipt: _, .. } => Rc::new(RemainsSupersededRevocationJoin::RemainsSupersededRevocationsJoined),
    RoadmapAcceptanceEvent::AcceptanceRevoked { exact_prior_receipt, disposition, .. } => match disposition.clone() {
    AcceptanceRevocationDisposition::AcceptanceNodeReopensActiveFrontier => Rc::new(RemainsSupersededRevocationJoin::RemainsSupersededRevocationsJoined),
    AcceptanceRevocationDisposition::AcceptanceNodeRemainsSuperseded => join_remains_superseded_to_declared_node(exact_prior_receipt.node.clone(), nodes, retired),
},
}
}

pub fn remains_superseded_revocations_join(history: Rc<Vec<Rc<RoadmapAcceptanceEvent>>>, nodes: Rc<Vec<Rc<RoadmapNode>>>, retired: Rc<Vec<NonEmptyStr>>) -> Rc<RemainsSupersededRevocationJoin> {
    history.iter().cloned().fold(Rc::new(RemainsSupersededRevocationJoin::RemainsSupersededRevocationsJoined), |acc: Rc<RemainsSupersededRevocationJoin>, event: Rc<RoadmapAcceptanceEvent>| match (*acc).clone() {
    RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnUnretiredNode { node: n, .. } => Rc::new(RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnUnretiredNode {
    node: n.clone(),
}),
    RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnUndeclaredNode { node: n, .. } => Rc::new(RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnUndeclaredNode {
    node: n.clone(),
}),
    RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnAmbiguousDeclaredNode { node: n, .. } => Rc::new(RemainsSupersededRevocationJoin::RemainsSupersededRevocationOnAmbiguousDeclaredNode {
    node: n.clone(),
}),
    RemainsSupersededRevocationJoin::RemainsSupersededRevocationsJoined => remains_superseded_revocation_event_join(event.clone(), nodes.clone(), retired.clone()),
})
}

pub fn node_ids_held_off_active_frontier(history: Rc<Vec<Rc<RoadmapAcceptanceEvent>>>, retired: Rc<Vec<NonEmptyStr>>) -> Rc<Vec<NonEmptyStr>> {
    {
        let withheld_by_replay = history.iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<NonEmptyStr>>, event: Rc<RoadmapAcceptanceEvent>| match (*event.clone()).clone() {
    RoadmapAcceptanceEvent::AcceptanceRecorded { receipt: receipt, .. } => Rc::new({ let mut __result = Vec::new(); for id in acc.iter().cloned() { if !(id.clone() == receipt.node.clone()) { __result.push(id); } } __result }),
    RoadmapAcceptanceEvent::AcceptanceRevoked { exact_prior_receipt, disposition, .. } => if revocation_reopens_active_frontier(disposition.clone()) {
            Rc::new({ let mut __result = Vec::new(); for id in acc.iter().cloned() { if !(id.clone() == exact_prior_receipt.node.clone()) { __result.push(id); } } __result })
        } else {
            v1_rt::concat(Rc::new({ let mut __result = Vec::new(); for id in acc.iter().cloned() { if !(id.clone() == exact_prior_receipt.node.clone()) { __result.push(id); } } __result }), Rc::new(vec![exact_prior_receipt.node.clone()]))
        },
});
retired.iter().cloned().fold(withheld_by_replay.clone(), |held: Rc<Vec<NonEmptyStr>>, id: NonEmptyStr| if roadmap_node_ids_contain(held.clone(), id.clone()) {
            held.clone()
        } else {
            v1_rt::concat(held.clone(), Rc::new(vec![id.clone()]))
        })
}
}

pub fn acceptance_history_integrity_verdict(history: Rc<Vec<Rc<RoadmapAcceptanceEvent>>>, prior_history: Rc<Vec<Rc<RoadmapAcceptanceEvent>>>) -> Rc<AcceptanceHistoryIntegrityVerdict> {
    if (((prior_history.clone().len() as i64) > 0) && !acceptance_history_extends_prior(prior_history.clone(), history.clone())) {
        Rc::new(AcceptanceHistoryIntegrityVerdict::AcceptanceHistoryIntegrityRefusedPriorPrefix {
    index: acceptance_history_prior_prefix_mismatch_index(prior_history.clone(), history.clone()),
})
    } else {
        match replay_acceptance_history(history.clone()) {
    std::option::Option::None => Rc::new(AcceptanceHistoryIntegrityVerdict::AcceptanceHistoryIntegrityRefusedReplay),
    Some(state) => match Rc::new({ let mut __result = Vec::new(); for r in state.ever_recorded.clone().iter().cloned() { if !ever_recorded_receipt_accounted_for(r.clone(), state.live.clone(), state.revoked.clone()) { __result.push(r); } } __result }).first().cloned() {
    Some(vanished) => Rc::new(AcceptanceHistoryIntegrityVerdict::AcceptanceHistoryIntegrityRefusedVanishedWithoutRevocation {
    receipt: vanished.clone(),
}),
    std::option::Option::None => Rc::new(AcceptanceHistoryIntegrityVerdict::AcceptanceHistoryIntegrityHolds),
},
}
    }
}

pub fn acceptance_history_integrity_holds(history: Rc<Vec<Rc<RoadmapAcceptanceEvent>>>, prior_history: Rc<Vec<Rc<RoadmapAcceptanceEvent>>>) -> bool {
    match (*acceptance_history_integrity_verdict(history, prior_history)).clone() {
    AcceptanceHistoryIntegrityVerdict::AcceptanceHistoryIntegrityHolds => true,
    AcceptanceHistoryIntegrityVerdict::AcceptanceHistoryIntegrityRefusedReplay => false,
    AcceptanceHistoryIntegrityVerdict::AcceptanceHistoryIntegrityRefusedVanishedWithoutRevocation { receipt: _, .. } => false,
    AcceptanceHistoryIntegrityVerdict::AcceptanceHistoryIntegrityRefusedPriorPrefix { index: _, .. } => false,
    AcceptanceHistoryIntegrityVerdict::AcceptanceHistoryIntegrityRefusedPriorHistoryObservation { detail: _, .. } => false,
}
}

